import{_ as r,C as i,o as t,c as s,a2 as o,b as d,w as n,a as l,E as c,a3 as m}from"./chunks/framework.Dd_iHz3e.js";const P=JSON.parse('{"title":"14.3 Networking & Communication Protocols","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.3-networking-and-communication.md","filePath":"system-design/14.3-networking-and-communication.md"}'),h={name:"system-design/14.3-networking-and-communication.md"};function p(u,e,g,T,k,S){const a=i("Mermaid");return t(),s("div",null,[e[1]||(e[1]=o('<h1 id="_14-3-networking-communication-protocols" tabindex="-1">14.3 Networking &amp; Communication Protocols <a class="header-anchor" href="#_14-3-networking-communication-protocols" aria-label="Permalink to &quot;14.3 Networking &amp; Communication Protocols&quot;">​</a></h1><h2 id="_1-plain-english-overview" tabindex="-1">1. Plain English Overview <a class="header-anchor" href="#_1-plain-english-overview" aria-label="Permalink to &quot;1. Plain English Overview&quot;">​</a></h2><p>Networking governs how data travels between client devices, smart sensors, cloud servers, and third-party APIs—covering transport protocols (TCP/UDP, HTTP/1.1 vs HTTP/2 vs HTTP/3) and communication patterns (REST, GraphQL, WebSockets, Server-Sent Events).</p><hr><h2 id="_2-usage-in-cooking-nexus" tabindex="-1">2. Usage in Cooking Nexus <a class="header-anchor" href="#_2-usage-in-cooking-nexus" aria-label="Permalink to &quot;2. Usage in Cooking Nexus&quot;">​</a></h2><ul><li><strong>REST over HTTP/1.1 &amp; HTTP/2</strong>: Used for CRUD operations (<code>/api/auth/login</code>, <code>/api/vision</code>, <code>/api/members/:id</code>).</li><li><strong>Server-Sent Events (SSE)</strong>: Used in [ai-stream.ts](file:///Users/avishjain/avishjain9-repos/26-cooking-nexus/27-kitchen-companion-pro/src/lib/ai-stream.ts) and [chef-ai/index.ts](file:///Users/avishjain/avishjain9-repos/26-cooking-nexus/27-kitchen-companion-pro/supabase/functions/chef-ai/index.ts) (<code>text/event-stream</code>) to stream AI recipe tokens.</li><li><strong>TLS 1.3</strong>: Secures all data in transit across public networks.</li></ul><hr><h2 id="_3-communication-protocol-flow" tabindex="-1">3. Communication Protocol Flow <a class="header-anchor" href="#_3-communication-protocol-flow" aria-label="Permalink to &quot;3. Communication Protocol Flow&quot;">​</a></h2>',8)),(t(),d(m,null,{default:n(()=>[c(a,{id:"mermaid-34",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20participant%20Sensor%20as%20Camera%20Sensor%0A%20%20%20%20participant%20Client%20as%20React%20SPA%20Client%0A%20%20%20%20participant%20Express%20as%20Express%20Backend%0A%20%20%20%20participant%20EdgeAI%20as%20Deno%20Edge%20(SSE)%0A%0A%20%20%20%20Sensor-%3E%3EExpress%3A%20HTTP%20POST%20%2Fapi%2Fvision%20(Short%20lived%2C%20TCP%20keep-alive)%0A%20%20%20%20Express--%3E%3ESensor%3A%20HTTP%20200%20JSON%20Response%0A%0A%20%20%20%20Client-%3E%3EEdgeAI%3A%20HTTP%20POST%20%2Ffunctions%2Fv1%2Fchef-ai%20(Persistent%20SSE%20channel)%0A%20%20%20%20loop%20Stream%20Output%0A%20%20%20%20%20%20%20%20EdgeAI--%3E%3EClient%3A%20data%3A%20%7B%22choices%22%3A%5B%7B%22delta%22%3A%7B...%7D%7D%5D%7D%5Cn%5Cn%0A%20%20%20%20end%0A%20%20%20%20EdgeAI--%3E%3EClient%3A%20data%3A%20%5BDONE%5D%5Cn%5Cn%20(Connection%20terminates)%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<hr><h2 id="_4-protocol-comparison-matrix" tabindex="-1">4. Protocol Comparison Matrix <a class="header-anchor" href="#_4-protocol-comparison-matrix" aria-label="Permalink to &quot;4. Protocol Comparison Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Protocol</th><th>Transport</th><th>Directionality</th><th>Connection Overhead</th><th>Firewall Friendly</th><th>Fit for Cooking Nexus</th></tr></thead><tbody><tr><td><strong>REST (HTTP/1.1 / H2)</strong></td><td>TCP</td><td>Request-Response</td><td>Low (reused sockets)</td><td>100%</td><td>Primary CRUD &amp; Telemetry</td></tr><tr><td><strong>Server-Sent Events</strong></td><td>TCP</td><td>Server to Client</td><td>Low (single HTTP stream)</td><td>100%</td><td>Optimal for AI Chat Streaming</td></tr><tr><td><strong>WebSockets</strong></td><td>TCP</td><td>Full-Duplex Bi-directional</td><td>High (Stateful sticky proxy)</td><td>90% (Some firewalls block)</td><td>Future live cooking streams</td></tr><tr><td><strong>gRPC / Protobuf</strong></td><td>HTTP/2</td><td>Bi-directional Binary</td><td>Ultra-Low (Binary framing)</td><td>Internal VPC only</td><td>Future inter-service RPC</td></tr><tr><td><strong>GraphQL</strong></td><td>HTTP</td><td>Client-defined queries</td><td>Moderate (Parsing tax)</td><td>100%</td><td>Unnecessary complexity for our schema</td></tr><tr><td><strong>MQTT</strong></td><td>TCP</td><td>Lightweight Pub/Sub</td><td>Ultra-Low (IoT micro-packets)</td><td>Requires MQTT broker</td><td>Future smart oven/scale bridge</td></tr></tbody></table><hr><h2 id="_5-trade-offs-accepted" tabindex="-1">5. Trade-offs Accepted <a class="header-anchor" href="#_5-trade-offs-accepted" aria-label="Permalink to &quot;5. Trade-offs Accepted&quot;">​</a></h2><ul><li><strong>SSE vs WebSockets</strong>: We chose SSE for AI streaming instead of WebSockets. SSE is strictly unidirectional, meaning the client cannot send additional voice feedback over the same open stream; however, it eliminates the operational headache of maintaining stateful WebSocket gateway clusters.</li></ul><hr><h2 id="_6-what-breaks-first-at-scale" tabindex="-1">6. What Breaks First at Scale? <a class="header-anchor" href="#_6-what-breaks-first-at-scale" aria-label="Permalink to &quot;6. What Breaks First at Scale?&quot;">​</a></h2><ul><li><strong>At 10x</strong>: TCP socket starvation on the Express server if IoT sensors open new connections instead of reusing HTTP keep-alive connections.</li><li><strong>At 100x</strong>: Client connection limits: HTTP/1.1 browser connection limits (max 6 sockets per domain) block multiple parallel AI streams unless upgraded to HTTP/2.</li><li><strong>At 1,000x</strong>: Global latency degradation for European and Asian cooks hitting a single US-East origin.</li></ul><hr><h2 id="_7-senior-engineer-improvements" tabindex="-1">7. Senior Engineer Improvements <a class="header-anchor" href="#_7-senior-engineer-improvements" aria-label="Permalink to &quot;7. Senior Engineer Improvements&quot;">​</a></h2><p>Deploy Cloudflare or AWS CloudFront with <strong>HTTP/3 (QUIC)</strong> enabled at the edge. HTTP/3 eliminates TCP head-of-line blocking, allowing cooks on lossy kitchen Wi-Fi to stream video reels and AI tokens without connection stalls.</p><hr><h2 id="_8-spoken-interview-answer-30-seconds" tabindex="-1">8. Spoken Interview Answer (30 Seconds) <a class="header-anchor" href="#_8-spoken-interview-answer-30-seconds" aria-label="Permalink to &quot;8. Spoken Interview Answer (30 Seconds)&quot;">​</a></h2><p>&quot;In Cooking Nexus, we strategically match protocols to communication patterns: standard REST over HTTP/2 for short-lived telemetry ingestion and authentication, and Server-Sent Events for streaming generative AI responses. We deliberately chose SSE over WebSockets for AI chat because it operates over standard HTTP, traverses firewalls seamlessly, and avoids stateful WebSocket connection cluster overhead while delivering real-time token streaming.&quot;</p>',15))])}const f=r(h,[["render",p]]);export{P as __pageData,f as default};
